const int mod=1e9+7;

int modpower(int a, int b)
{
    int r=1;

    a=a%mod;
    while(b>0)
    {
        if(b%2==1)
        {
            r*=a;
            r%=mod;
        }

        b=b/2;
        a*=a;
        a%=mod;

    }

    return r;
}


